const LEVEL_LABEL = { "domestic": "Domestic", "light-commercial": "Light Commercial", "heavy-commercial": "Heavy Commercial" };

const legalCache = new Map();
async function legal(file) {
  if (!legalCache.has(file)) {
    legalCache.set(file, frontMatter(await readFile(path.join(ROOT, "content/legal", file), "utf8")));
  }
  return legalCache.get(file);
}

export function leadForm(source) {
  return `<form class="form" data-lead-form data-source="${source}" method="post" action="/api/lead" novalidate>
  <input type="hidden" name="source" value="${source}">
  <label>Your name<input name="name" autocomplete="name" required maxlength="200"></label>
  <label>Email<input type="email" name="email" autocomplete="email" required maxlength="200"></label>
  <label>Company<input name="company" autocomplete="organization" maxlength="200"></label>
  <label>Phone<input type="tel" name="phone" autocomplete="tel" maxlength="40"></label>
  <label>What do you need?<textarea name="need" maxlength="2000" required></textarea></label>
  <div class="hp" aria-hidden="true"><label>Leave this empty<input name="website" tabindex="-1" autocomplete="off"></label></div>
  <p class="small">We use these details only to reply to you. <a href="/legal/privacy/">Privacy Policy</a>.</p>
  <p class="form-status" data-status aria-live="polite"></p>
  <div><button class="btn btn-hivis" type="submit">Send enquiry</button></div>
</form>`;
}

// -- checks and output ---------------------------------------------------------

function textOf(html) {
  return html.replace(/<script[\s\S]*?<\/script>/g, " ").replace(/<[^>]+>/g, " ").replace(/&[a-z#0-9]+;/g, " ");
}

async function main() {
  await rm(DIST, { recursive: true, force: true });
  await mkdir(DIST, { recursive: true });
  await cp(path.join(ROOT, "public"), DIST, { recursive: true });
  await build();
  const urls = new Set(pages.map((p) => p.url));
  const titles = new Map();
  for (const p of pages) {
    const out = p.url.endsWith(".html") ? path.join(DIST, p.url) : path.join(DIST, p.url, "index.html");
    await mkdir(path.dirname(out), { recursive: true });
    await writeFile(out, p.html);
    if (!p.url.startsWith("/legal/")) {
      let text = textOf(p.html);
      for (const re of BANNED_ALLOWED) text = text.replace(re, "");
      const hits = text.match(BANNED);
      if (hits) problems.push(`${p.url}: banned wording: ${[...new Set(hits)].join(", ")}`);
    }
    if (titles.has(p.title)) problems.push(`${p.url}: duplicate title with ${titles.get(p.title)}`);
    titles.set(p.title, p.url);
    for (const [, href] of p.html.matchAll(/href="(\/[^"#?]*)/g)) {
      if (href.startsWith("/assets/")) continue;
      if (!urls.has(href)) problems.push(`${p.url}: broken link ${href}`);
    }
    if (Buffer.byteLength(p.html) > 100_000) problems.push(`${p.url}: page is ${Math.round(Buffer.byteLength(p.html) / 1024)} KB (limit 100 KB)`);
  }
  const indexable = pages.filter((p) => !p.url.endsWith(".html") && !p.url.startsWith("/order/") && p.url !== "/cart/");
  await writeFile(path.join(DIST, "sitemap.xml"), `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${indexable.map((p) => `  <url><loc>${ORIGIN}${p.url}</loc></url>`).join("\n")}
</urlset>
`);
  const cat = JSON.parse(await readFile(CATALOGUE, "utf8"));
  await writeFile(path.join(DIST, "robots.txt"), cat.preview
    ? "User-agent: *\nDisallow: /\n"
    : `User-agent: *\nDisallow: /cart/\nDisallow: /order/\nDisallow: /api/\nSitemap: ${ORIGIN}/sitemap.xml\n`);
  await writeFile(path.join(DIST, "build-info.json"), JSON.stringify({
    built_at: new Date().toISOString(), catalogue_generated_at: cat.generated_at, preview: cat.preview,
    pricing_revision: cat.pricing_revision, pages: pages.length,
  }, null, 1));

  console.log(`Built ${pages.length} pages into dist/${cat.preview ? " (PREVIEW catalogue)" : ""}`);
  const blocking = problems.filter((p) => PRODUCTION || !/open item/.test(p) && !/PREVIEW/.test(p));
  for (const p of problems) console.log(`  ${blocking.includes(p) ? "ERROR" : "note "}: ${p}`);
  if (blocking.length) {
    console.error(`${blocking.length} problem(s) must be fixed${PRODUCTION ? " before a production build" : ""}.`);
    process.exit(1);
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
